-- Keep the qualified480 claim implementation as a service-only inner authority.
-- The wrapper retains copy-before-account ordering and adds durable retirement
-- before the original account-wide running-operation check.
do $seller_claim_base$
begin
  if to_regprocedure('public.ebay_seller_operation_claim_base480_v1(uuid,uuid,uuid,text,bigint,text,uuid)') is null then
    alter function public.ebay_seller_operation_claim_v1(uuid,uuid,uuid,text,bigint,text,uuid)
      rename to ebay_seller_operation_claim_base480_v1;
  end if;
end $seller_claim_base$;

create or replace function public.ebay_seller_operation_claim_v1(
  p_actor uuid,p_draft_id uuid,p_request_id uuid,p_kind text,
  p_expected_revision bigint,p_expected_hash text,p_claim_nonce uuid
)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare d public.ebay_seller_drafts_v1; expired public.ebay_seller_operations_v1;
  instant timestamptz;
begin
  perform public.ebay_seller_require_actor_v1(p_actor);
  select * into d from public.ebay_seller_drafts_v1 where id=p_draft_id and user_id=p_actor;
  if not found then raise exception 'seller_draft_not_owned' using errcode='42501'; end if;
  perform 1 from public.vault_item_instances where id=d.instance_id and user_id=p_actor for update;
  if not found then raise exception 'seller_exact_active_copy_required' using errcode='22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended('ebay-seller-account:'||d.account_id::text,0));
  instant:=clock_timestamp();
  for expired in select * from public.ebay_seller_operations_v1
      where user_id=p_actor and account_id=d.account_id and status='running'
        and not handoff_ready and lease_until<=instant
      order by created_at,id for update
  loop
    update public.ebay_seller_operations_v1 set status='uncertain',
      error_code='seller_operation_result_uncertain',updated_at=instant,
      receipts=receipts||jsonb_build_array(jsonb_build_object('stage','lease_expired','at',instant,
        'evidence',jsonb_build_object('kind','worker_lease_expired','priorStage',expired.stage,
          'reservationPreserved',true))) where id=expired.id;
    if expired.kind<>'reconcile' then
      update public.ebay_seller_drafts_v1 set state='uncertain',
        error_code='seller_operation_result_uncertain',updated_at=instant where id=expired.draft_id;
    end if;
    if expired.kind='prepare' then
      update public.ebay_seller_photos_v1 set state='uncertain',updated_at=instant
        where draft_id=expired.draft_id and state='uploading';
    end if;
  end loop;
  -- Acknowledged preparation handoffs are deliberately excluded above. Resume
  -- continues their saved operation under a fresh nonce, even after a pause.
  return public.ebay_seller_operation_claim_base480_v1(p_actor,p_draft_id,p_request_id,
    p_kind,p_expected_revision,p_expected_hash,p_claim_nonce);
end $$;

-- A provider read can prove a pre-intent interrupted claim was never published.
-- Delegate all original receipt/nonce/ownership checks before resolving it.
do $seller_complete_base$
begin
  if to_regprocedure('public.ebay_seller_operation_complete_base480_v1(uuid,uuid,uuid,jsonb,text)') is null then
    alter function public.ebay_seller_operation_complete_v1(uuid,uuid,uuid,jsonb,text)
      rename to ebay_seller_operation_complete_base480_v1;
  end if;
end $seller_complete_base$;

create or replace function public.ebay_seller_operation_complete_v1(
  p_actor uuid,p_operation_id uuid,p_claim_nonce uuid,p_receipt jsonb,
  p_review_json text default null
)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare result jsonb; op public.ebay_seller_operations_v1;
  d public.ebay_seller_drafts_v1; publication public.ebay_seller_operations_v1;
  reservation public.ebay_seller_reservations_v1; evidence jsonb; instant timestamptz;
begin
  result:=public.ebay_seller_operation_complete_base480_v1(p_actor,p_operation_id,p_claim_nonce,
    p_receipt,p_review_json);
  if result->>'status'<>'succeeded' or result->>'recovered'='true'
      or p_receipt->>'state' is distinct from 'unpublished'
      or p_receipt->>'listingId' is not null then return result; end if;
  select * into strict op from public.ebay_seller_operations_v1 where id=p_operation_id;
  if op.kind<>'reconcile' then return result; end if;
  select * into strict d from public.ebay_seller_drafts_v1 where id=op.draft_id;
  if d.listing_id is not null or d.state<>'uncertain' then return result; end if;
  select * into reservation from public.ebay_seller_reservations_v1
    where draft_id=d.id and user_id=p_actor and released_at is null for update;
  if not found then return result; end if;
  select * into strict publication from public.ebay_seller_operations_v1
    where id=reservation.publication_operation_id for update;
  if publication.kind<>'publish' or publication.status<>'uncertain' or publication.stage<>'claimed'
      or publication.user_id<>p_actor or publication.draft_id<>d.id
      or not (publication.receipts @> '[{"stage":"lease_expired","evidence":{"reservationPreserved":true}}]')
      or exists(select 1 from public.ebay_seller_operations_v1 other
        where other.draft_id=d.id and other.kind='publish' and other.id<>publication.id
          and (other.stage<>'claimed' or other.status='running')) then return result; end if;
  instant:=clock_timestamp();
  evidence:=jsonb_build_object('kind','provider_unpublished_and_no_publish_intent',
    'publicationOperationId',publication.id,'observationOperationId',op.id,'offerId',d.offer_id);
  update public.ebay_seller_operations_v1 set status='failed',error_code='seller_publication_not_started',
    updated_at=instant,receipts=receipts||jsonb_build_array(jsonb_build_object('stage','not_published','at',instant,
      'evidence',jsonb_build_object('kind','no_publish_intent','providerObservationId',op.id)))
    where id=publication.id;
  update public.ebay_seller_reservations_v1 set released_at=instant,release_operation_id=op.id,
    release_evidence=evidence where id=reservation.id;
  update public.ebay_seller_drafts_v1 set state='prepared',error_code=null,updated_at=instant where id=d.id;
  return result||jsonb_build_object('state','prepared');
end $$;

revoke all on function public.ebay_seller_operation_claim_v1(uuid,uuid,uuid,text,bigint,text,uuid)
  from public,anon,authenticated;
revoke all on function public.ebay_seller_operation_claim_base480_v1(uuid,uuid,uuid,text,bigint,text,uuid)
  from public,anon,authenticated;
grant execute on function public.ebay_seller_operation_claim_v1(uuid,uuid,uuid,text,bigint,text,uuid)
  to service_role;
grant execute on function public.ebay_seller_operation_claim_base480_v1(uuid,uuid,uuid,text,bigint,text,uuid)
  to service_role;
revoke all on function public.ebay_seller_operation_complete_v1(uuid,uuid,uuid,jsonb,text)
  from public,anon,authenticated;
revoke all on function public.ebay_seller_operation_complete_base480_v1(uuid,uuid,uuid,jsonb,text)
  from public,anon,authenticated;
grant execute on function public.ebay_seller_operation_complete_v1(uuid,uuid,uuid,jsonb,text) to service_role;
grant execute on function public.ebay_seller_operation_complete_base480_v1(uuid,uuid,uuid,jsonb,text) to service_role;

commit;
